"""Build a self-contained glTF from verified Fusion display meshes."""
import argparse
import hashlib
import json
from pathlib import Path
import struct

import numpy as np


# These body families are generated by the project's original CAD builders.
# A mixed group must be re-exported from Fusion before it can be published.
PUBLIC_PREFIXES = ("original ", "intake candidate ", "cartridge ", "frame fastening ",
                   "visual digit ", "fixed bumper ", "aft-electrical-beam", "aft-adapter",
                   "aft-crush-sleeve", "aft-bolt-", "battery-tray", "battery-end-stop",
                   "battery-strap", "battery-foot-bolt", "battery-top-", "battery-insulating-pad",
                   "pdh-bolt-", "candidate 1p5mm outer belt tread")


def public_body(name):
    return name.startswith(PUBLIC_PREFIXES) or name in PUBLIC_NAMES


ELECTRICAL = Path(__file__).resolve().parents[2] / "cad/electrical/manifest.json"
PUBLIC_NAMES = {"Continuous covered bumper envelope"} | {
    item["id"] for item in json.loads(ELECTRICAL.read_bytes())["components"] if item["role"] != "service"
}


def build(manifest, output, public):
    source = json.loads(manifest.read_bytes())
    if source["sourceFormat"] != "F3D" or source["units"] != "mm" or source["frame"] != "robot-floor-XYZ":
        raise ValueError("Expected the millimetre Fusion robot-floor export")
    names = {row["key"]: row["name"] for row in source["bodyInventory"]}
    model = {"asset": {"version": "2.0", "extras": {"nativeSha256": source["sourceSha256"]}}, "scene": 0, "scenes": [{"nodes": []}],
             "nodes": [], "meshes": [], "materials": [], "accessors": [], "bufferViews": []}
    binary = bytearray()

    def accessor(values, shape, component, target, bounds=False):
        binary.extend(b"\0" * (-len(binary) % 4))
        view = {"buffer": 0, "byteOffset": len(binary), "byteLength": values.nbytes, "target": target}
        item = {"bufferView": len(model["bufferViews"]), "componentType": component,
                "count": len(values), "type": shape}
        if bounds:
            item.update(min=values.min(axis=0).tolist(), max=values.max(axis=0).tolist())
        model["bufferViews"].append(view)
        model["accessors"].append(item)
        binary.extend(values.tobytes())
        return len(model["accessors"]) - 1

    for group in source["meshes"]:
        if group["name"].endswith("reserved-space"):
            continue
        keys = group["sourceBodyKeys"]
        if not keys or any(key not in names for key in keys):
            raise ValueError("Missing native body provenance")
        if public and any(not public_body(names[k]) for k in keys):
            raise ValueError("Group contains geometry outside the public body allowlist")
        raw = (manifest.parent / group["file"]).read_bytes()
        count = struct.unpack_from("<I", raw, 80)[0]
        if (hashlib.sha256(raw).hexdigest() != group["sha256"] or
                len(raw) != 84 + 50 * count or count != group["triangles"]):
            raise ValueError("Fusion STL differs from its recorded export")
        dtype = np.dtype([("normal", "<f4", 3), ("vertices", "<f4", (3, 3)), ("attr", "<u2")])
        cad = np.frombuffer(raw, offset=84, dtype=dtype)["vertices"]
        xyz = cad[:, :, [0, 2, 1]].copy() * .001
        xyz[:, :, 2] *= -1  # Robot Z-up to glTF Y-up, retaining handedness.
        normals = np.cross(xyz[:, 1]-xyz[:, 0], xyz[:, 2]-xyz[:, 0])
        lengths = np.linalg.norm(normals, axis=1)
        valid = lengths > 0
        normals = normals[valid] / lengths[valid, None]
        vertices = np.column_stack((xyz[valid].reshape(-1, 3), np.repeat(normals, 3, axis=0)))
        unique, indices = np.unique(vertices, axis=0, return_inverse=True)
        pos = accessor(unique[:, :3].astype("<f4"), "VEC3", 5126, 34962, True)
        normal = accessor(unique[:, 3:].astype("<f4"), "VEC3", 5126, 34962)
        index = accessor(indices.ravel().astype("<u4"), "SCALAR", 5125, 34963)
        rgb = np.asarray(group["rgba"][:3])
        linear = np.where(rgb <= .04045, rgb/12.92, ((rgb+.055)/1.055)**2.4)
        material = {"baseColorFactor": [*linear, 1], "metallicFactor": .18, "roughnessFactor": .56}
        slot = len(model["nodes"])
        model["materials"].append({"pbrMetallicRoughness": material})
        model["meshes"].append({"primitives": [{"attributes": {"POSITION": pos, "NORMAL": normal},
                                               "indices": index, "material": slot}]})
        model["nodes"].append({"mesh": slot, "name": group["name"]})
        model["scenes"][0]["nodes"].append(slot)

    binary.extend(b"\0" * (-len(binary) % 4))
    model["buffers"] = [{"byteLength": len(binary)}]
    header = json.dumps(model, separators=(",", ":"), allow_nan=False).encode()
    header += b" " * (-len(header) % 4)
    output.write_bytes(struct.pack("<4sIIII", b"glTF", 2, 28+len(header)+len(binary),
                                   len(header), 0x4E4F534A) + header
                       + struct.pack("<II", len(binary), 0x004E4942) + binary)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("manifest", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--public", action="store_true", help="Require project-authored bodies in every group")
    args = parser.parse_args()
    build(args.manifest, args.output, args.public)
